import{_ as n}from"./chunks/panel-workspace.DfVZw37W.js";import{_ as d,C as s,o as i,c as l,a2 as a,j as o,a as t,E as h}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"Panel Workbench","description":"The panel workbench is where a page becomes structured data. Automatic detection is only a starting point; the workbench is built for correcting it…","frontmatter":{"description":"The panel workbench is where a page becomes structured data. Automatic detection is only a starting point; the workbench is built for correcting it…"},"headers":[],"relativePath":"guide/panels.md","filePath":"guide/panels.md","lastUpdated":1794727111000}'),c={name:"guide/panels.md"};function g(p,e,m,u,b,w){const r=s("Badge");return i(),l("div",null,[e[6]||(e[6]=a('<h1 id="panel-workbench" tabindex="-1">Panel Workbench <a class="header-anchor" href="#panel-workbench" aria-label="Permalink to &quot;Panel Workbench&quot;">​</a></h1><p>The panel workbench is where a page becomes structured data. Automatic detection is only a starting point; the workbench is built for correcting it, quickly and reversibly.</p><figure class="shot"><img src="'+n+'" alt="Panel workbench with four detected panels, resize handles and the annotation toolbar"><figcaption>Detected panels are drawn as numbered boxes over the base image. The selected box shows eight resize handles. The annotation toolbar sits below the panel tools.</figcaption></figure><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Every later feature depends on panels: compare reading, panel-scoped notes, PNG panel export, HTML export. If the boxes are wrong, everything downstream is wrong. Automatic detection gets most pages right, but splash pages, spread pages, edge strips and unusual layouts always need a hand.</p><h2 id="the-toolbar-control-by-control" tabindex="-1">The toolbar, control by control <a class="header-anchor" href="#the-toolbar-control-by-control" aria-label="Permalink to &quot;The toolbar, control by control&quot;">​</a></h2><h3 id="row-1-—-base-image-and-splitting" tabindex="-1">Row 1 — base image and splitting <a class="header-anchor" href="#row-1-—-base-image-and-splitting" aria-label="Permalink to &quot;Row 1 — base image and splitting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Base image</strong> selector</td><td>Chooses which language&#39;s artwork is shown and used for detection.</td><td>Panel rectangles are shared by all languages on the page, so this only changes the picture you draw on.</td></tr><tr><td>Detector chip</td><td>Shows the algorithm version that produced the current panels, e.g. <code>xycut-1.3</code>, <code>layout:&lt;id&gt;</code>, <code>plugin:&lt;name&gt;</code>.</td><td><code>Legacy data</code> means the page JSON predates version tracking.</td></tr><tr><td>Status text</td><td>Shows whether the panels are <em>Auto</em>, <em>Template</em>, <em>Plugin</em> or <em>Manually edited</em>, plus the save count and the last edit summary.</td><td>This is an edit counter, not an audit log.</td></tr><tr><td><strong>Auto split</strong></td><td>Runs detection on the base image and replaces the current panels.</td><td>Disabled while detection is running or when the page has no image. Re-running detection discards hand edits.</td></tr><tr><td><strong>Add panel</strong></td><td>Adds a default panel near the centre of the page.</td><td>Faster alternative: double-click empty space.</td></tr><tr><td><strong>Merge (n)</strong></td><td>Merges the selected panels into one box with <code>source: &quot;merged&quot;</code>.</td><td>Enabled with two or more selected panels.</td></tr><tr><td><strong>Delete</strong></td><td>Deletes the selected panels and their panel-scoped notes.</td><td>Same as <code>Delete</code> / <code>Backspace</code>.</td></tr></tbody></table><h3 id="row-1-—-saving" tabindex="-1">Row 1 — saving <a class="header-anchor" href="#row-1-—-saving" aria-label="Permalink to &quot;Row 1 — saving&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Auto</strong></td><td>Saves automatically about 0.7 s after a change.</td></tr><tr><td><strong>Confirm</strong></td><td>Keeps edits dirty until you click <strong>✓</strong> or press <code>Enter</code>. <strong>×</strong> or <code>Esc</code> discards and restores the last save.</td></tr><tr><td><code>↶</code> / <code>↷</code></td><td>Undo / redo (<code>Ctrl+Z</code>, <code>Ctrl+Shift+Z</code>, <code>Ctrl+Y</code>).</td></tr><tr><td><strong>✓</strong></td><td>Saves the dirty page (Confirm mode only).</td></tr><tr><td><strong>×</strong></td><td>Discards unsaved edits (Confirm mode only).</td></tr><tr><td><strong>Unsaved</strong> flag</td><td>Appears in Confirm mode while the page has unsaved changes.</td></tr><tr><td><strong>Numbers</strong></td><td>Shows or hides the panel index badges.</td></tr></tbody></table><p>The save mode is remembered in the browser. The top bar always shows the current state: <em>Saved</em>, <em>Saving…</em>, <em>Pending save</em> or <em>Unsaved changes</em>.</p><h3 id="row-1-—-zoom" tabindex="-1">Row 1 — zoom <a class="header-anchor" href="#row-1-—-zoom" aria-label="Permalink to &quot;Row 1 — zoom&quot;">​</a></h3><p>The <code>−</code> / percentage / <code>＋</code> control changes the stage zoom from 50% to 300% in 15% steps. Zoom is a display setting only; panel coordinates are normalized to <code>0..1</code> and do not change.</p><h3 id="row-2-—-numeric-rectangle" tabindex="-1">Row 2 — numeric rectangle <a class="header-anchor" href="#row-2-—-numeric-rectangle" aria-label="Permalink to &quot;Row 2 — numeric rectangle&quot;">​</a></h3><p>With exactly one panel selected, the second row shows <strong>Panel rect</strong> with four percentage inputs:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>X</code></td><td>Left edge, percent of page width.</td></tr><tr><td><code>Y</code></td><td>Top edge, percent of page height.</td></tr><tr><td><code>W</code></td><td>Width, percent of page width.</td></tr><tr><td><code>H</code></td><td>Height, percent of page height.</td></tr></tbody></table><p>Typing a value updates the panel immediately. Values outside the page are clamped when saved.</p><h3 id="row-2-—-grid-generator" tabindex="-1">Row 2 — grid generator <a class="header-anchor" href="#row-2-—-grid-generator" aria-label="Permalink to &quot;Row 2 — grid generator&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Range</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Rows</strong></td><td>1–8</td><td>Number of rows.</td></tr><tr><td><strong>Columns</strong></td><td>1–6</td><td>Number of columns.</td></tr><tr><td><strong>Gap</strong></td><td>0–8 %</td><td>Gutter between cells, in percent of the page.</td></tr><tr><td><strong>Generate grid</strong></td><td>—</td><td>Replaces the current panels with an evenly divided grid.</td></tr></tbody></table><p>Use the grid for a chapter with a fixed magazine layout; use <strong>Panel templates</strong> when the layout repeats exactly.</p><h3 id="row-2-—-templates-and-json" tabindex="-1">Row 2 — templates and JSON <a class="header-anchor" href="#row-2-—-templates-and-json" aria-label="Permalink to &quot;Row 2 — templates and JSON&quot;">​</a></h3><p><strong>Panel templates</strong> captures the rectangles of the current page:</p><ol><li>Open <strong>Panel templates</strong>, type a name, click <strong>Save this page as a template</strong>.</li><li>Select the template, then <strong>Apply to this page</strong> or <strong>Apply to chapter</strong>.</li><li>Applying to a chapter asks for confirmation because existing panels are overwritten.</li></ol><p>When the new page has the same number of panels as the template, panel-scoped notes are remapped by reading order. When the count differs, panel notes are dropped rather than silently attached to the wrong panel; page notes are always kept. Templates live in <code>data/templates/panel.json</code>.</p><p><strong>Copy JSON path</strong> copies <code>data/pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</code>. Editing that file by hand is supported; the server normalizes rectangles, repairs missing ids and drops dangling references on read.</p><h2 id="mouse-and-keyboard-on-the-canvas" tabindex="-1">Mouse and keyboard on the canvas <a class="header-anchor" href="#mouse-and-keyboard-on-the-canvas" aria-label="Permalink to &quot;Mouse and keyboard on the canvas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Gesture</th></tr></thead><tbody><tr><td>Move a panel</td><td>Drag the box body.</td></tr><tr><td>Resize</td><td>Drag one of the eight handles.</td></tr><tr><td>Add a panel quickly</td><td>Double-click empty space.</td></tr><tr><td>Draw a panel precisely</td><td>Drag on empty space.</td></tr><tr><td>Constrain to a square</td><td>Hold <code>Shift</code> while drawing.</td></tr><tr><td>Disable snapping</td><td>Hold <code>Alt</code> while drawing or dragging.</td></tr><tr><td>Cancel the current box</td><td><code>Esc</code>.</td></tr><tr><td>Multi-select</td><td><code>Ctrl</code>-click or <code>Shift</code>-click boxes.</td></tr><tr><td>Nudge</td><td>Arrow keys move the selection by 0.2%; <code>Shift</code> + arrow moves by 1%.</td></tr><tr><td>Delete</td><td><code>Delete</code> or <code>Backspace</code>.</td></tr><tr><td>Save / discard (Confirm mode)</td><td><code>Enter</code> / <code>Esc</code>.</td></tr></tbody></table><p>All coordinates are normalized to the page, so a panel stays in the same place at any zoom level or export resolution.</p><h2 id="numbering-and-reading-direction" tabindex="-1">Numbering and reading direction <a class="header-anchor" href="#numbering-and-reading-direction" aria-label="Permalink to &quot;Numbering and reading direction&quot;">​</a></h2><ul><li><strong>Numbers</strong> toggles the index badges.</li><li>Reading direction is stored per page: <code>rtl</code> (right to left, top to bottom), <code>ltr</code> (left to right, top to bottom) or <code>ttb</code> (right to left, vertical columns). Change it in the top bar.</li><li>A panel may carry an explicit <code>number</code> that overrides automatic reading order; otherwise numbering is derived from the rectangle and the direction.</li><li>The same order drives the compare reader, the notes overview and HTML export.</li></ul><div class="tip custom-block"><p class="custom-block-title">Reading order first</p><p>If panel numbers look wrong before you start editing, fix the reading-direction selector first. Renumbering by hand is possible in the JSON, but changing the direction fixes every page in the chapter.</p></div><h2 id="annotation-tools" tabindex="-1">Annotation tools <a class="header-anchor" href="#annotation-tools" aria-label="Permalink to &quot;Annotation tools&quot;">​</a></h2><p>The annotation layer draws on top of the artwork and is stored separately from panels.</p><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Annotations: Shown / Hidden</strong></td><td>Global visibility. Hiding keeps the data and hides it in exports.</td></tr><tr><td><strong>Select and move</strong></td><td>Select an existing mark; drag to move it.</td></tr><tr><td><strong>Arrow</strong></td><td>Drag from tail to head.</td></tr><tr><td><strong>Rectangle</strong> / <strong>Ellipse</strong></td><td>Drag a box or oval.</td></tr><tr><td><strong>Highlighter</strong></td><td>Semi-transparent freehand stroke.</td></tr><tr><td><strong>Freehand</strong></td><td>Opaque pen stroke; keeps the full polyline.</td></tr><tr><td><strong>Text</strong></td><td>Click, then type the label.</td></tr><tr><td><strong>Number badge</strong></td><td>Click, then type a number.</td></tr><tr><td><strong>Mosaic</strong></td><td>Drag a rectangle; the area is pixelated.</td></tr><tr><td><strong>Colour swatches</strong></td><td>Sets the colour for new marks; clicking a swatch while a mark is selected recolours it.</td></tr><tr><td><strong>Delete</strong></td><td>Deletes the selected mark.</td></tr><tr><td><strong>Clear all</strong></td><td>Deletes every mark on the page after confirmation.</td></tr></tbody></table><p>Scope follows the selection: with one panel selected, the hint reads <em>New marks go inside panel N</em>; with nothing selected, <em>New marks cover the whole page</em>. <code>Esc</code> leaves the current tool or deselects a mark.</p><p>Exported HTML and PNG include annotations only when the layer is shown. The HTML export also has a <strong>Draw panel borders on the original image</strong> option, which is separate from annotations.</p><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2>',37)),o("p",null,[e[0]||(e[0]=t("The page JSON has a ",-1)),e[1]||(e[1]=o("code",null,"groups",-1)),e[2]||(e[2]=t(" field (",-1)),e[3]||(e[3]=o("code",null,"{ id, name, panelIds, number }",-1)),e[4]||(e[4]=t(") and it is preserved on read, write, import and export. ",-1)),h(r,{type:"warning",text:"Planned"}),e[5]||(e[5]=t(" There is no in-app UI for creating or editing groups yet; only direct JSON editing changes them.",-1))]),e[7]||(e[7]=a('<h2 id="a-safe-correction-workflow" tabindex="-1">A safe correction workflow <a class="header-anchor" href="#a-safe-correction-workflow" aria-label="Permalink to &quot;A safe correction workflow&quot;">​</a></h2><ol><li>Open the page and let automatic detection run.</li><li>Fix obvious boxes: move, resize, add, delete.</li><li>Merge splash-page panels that span a spread.</li><li>Save (or press <code>✓</code> in Confirm mode).</li><li>Switch to <strong>Compare</strong> (<code>C</code>) and check that the same panel really contains the same artwork.</li></ol><p>Avoid re-running <strong>Auto split</strong> after hand edits unless you are willing to lose them.</p><figure class="shot"><div class="shot-missing"><strong>Screenshot pending: panel toolbar close-up</strong> A cropped screenshot of the two toolbar rows and the annotation toolbar will be added here. </div><figcaption>Planned screenshot: toolbar controls with numbered callouts.</figcaption></figure><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>Auto split replaced my boxes.</strong> Detection overwrites. Use a panel template or edit by hand after the first successful split.</li><li><strong>A page has no image.</strong> Detection is disabled and the stage shows an empty state. Add the missing language folder or map it in volume settings.</li><li><strong>WebP pages do not detect.</strong> WebP is displayed but not decoded for detection; convert to JPEG or PNG.</li><li><strong>Panel notes disappeared after applying a template.</strong> The template had a different panel count, so panel notes were dropped; page notes were kept. Restore from a backup if needed.</li><li><strong>“Unsaved changes” will not go away.</strong> You are in Confirm mode. Press <code>✓</code> or <code>Enter</code>; <code>×</code> discards.</li><li><strong>Marks are invisible.</strong> The annotation layer is hidden, or a panel filter is active. Check <strong>Annotations: Shown</strong>.</li></ul><h2 id="missing-screenshots" tabindex="-1">Missing screenshots <a class="header-anchor" href="#missing-screenshots" aria-label="Permalink to &quot;Missing screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Needed for</th></tr></thead><tbody><tr><td>toolbar close-up</td><td>Row 1 and row 2 controls</td></tr><tr><td>annotation toolbar close-up</td><td>Tool icons and colour swatches</td></tr><tr><td>panel template panel</td><td>Template save / apply controls</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/compare">Compare Reader</a> — what panels are for.</li><li><a href="/KomaYomi-docs/data-format">Data Formats</a> — the page JSON contract.</li><li><a href="/KomaYomi-docs/guide/shortcuts">Keyboard Shortcuts</a> — one table for every key.</li></ul>',10))])}const v=d(c,[["render",g]]);export{k as __pageData,v as default};
